test('getTabProps aria-controls matches getPanelProps id', () => {
  const { result } = renderHook(() => useHeadlessTabs(['First']));
  const tabProps = result.current.getTabProps('First');
  const panelProps = result.current.getPanelProps('First');
  expect(tabProps['aria-controls']).toBe(panelProps.id);
});

