import { useState, useCallback, useId } from 'react';

export function useHeadlessTabs(tabs: string[]) {
  const [activeTab, setActiveTab] = useState(tabs[0]);
  const baseId = useId();

  const getTabId = (tab: string) => `${baseId}-tab-${tab.replace(/\s+/g, '-')}`;
  const getPanelId = (tab: string) => `${baseId}-panel-${tab.replace(/\s+/g, '-')}`;

  const getTabProps = useCallback((tab: string) => ({
    role: 'tab' as const,
    id: getTabId(tab),
    'aria-selected': activeTab === tab,
    'aria-controls': getPanelId(tab),
    tabIndex: activeTab === tab ? 0 : -1,
    onClick: () => setActiveTab(tab),
  }), [activeTab, baseId]);

  const getPanelProps = useCallback((tab: string) => ({
    role: 'tabpanel' as const,
    id: getPanelId(tab),
    'aria-labelledby': getTabId(tab),
    hidden: activeTab !== tab,
  }), [activeTab, baseId]);

  return { activeTab, setActiveTab, getTabProps, getPanelProps };
}
